)
SELECT
  '1fc8d835-e58e-5be5-8ff7-aa4da2948ec3',
  'SMD 25Q32',
  'SMD 25Q32',
  NULL,
  7,
  true,
  (SELECT id_categoria FROM electronica_az.categoria WHERE lower(btrim(nombre)) = lower('Integrados') LIMIT 1),
  (SELECT id_unidad_medida FROM electronica_az.unidad_medida WHERE lower(btrim(simbolo)) = lower('UND') LIMIT 1),
  (SELECT id_ubicacion FROM electronica_az.ubicacion WHERE lower(btrim(codigo)) = lower('113') LIMIT 1),
  NULL,
  NULL
WHERE (SELECT id_ubicacion FROM electronica_az.ubicacion WHERE lower(btrim(codigo)) = lower('113') LIMIT 1) IS NOT NULL
ON CONFLICT (codigo) DO UPDATE SET
  nombre = EXCLUDED.nombre,
  descripcion = EXCLUDED.descripcion,
  precio_venta = EXCLUDED.precio_venta,
  activo = true,
  id_categoria = EXCLUDED.id_categoria,
  id_ubicacion = EXCLUDED.id_ubicacion;
