  id_producto, codigo, nombre, descripcion, precio_venta, activo,
  id_categoria, id_unidad_medida, id_ubicacion, id_marca, id_modelo
)
SELECT
  '6b27c863-5f6b-5e5e-93f6-62d9a79cd27e',
  'WS2812B',
  'WS2812B',
  'RGB',
  15,
  true,
  (SELECT id_categoria FROM electronica_az.categoria WHERE lower(btrim(nombre)) = lower('Modulos Arduino') LIMIT 1),
  (SELECT id_unidad_medida FROM electronica_az.unidad_medida WHERE lower(btrim(simbolo)) = lower('UND') LIMIT 1),
  (SELECT id_ubicacion FROM electronica_az.ubicacion WHERE lower(btrim(codigo)) = lower('SIN-CAJA') LIMIT 1),
  NULL,
  NULL
WHERE (SELECT id_ubicacion FROM electronica_az.ubicacion WHERE lower(btrim(codigo)) = lower('SIN-CAJA') LIMIT 1) IS NOT NULL
ON CONFLICT (codigo) DO UPDATE SET
  nombre = EXCLUDED.nombre,
  descripcion = EXCLUDED.descripcion,
  precio_venta = EXCLUDED.precio_venta,
  activo = true,
  id_categoria = EXCLUDED.id_categoria,
  id_ubicacion = EXCLUDED.id_ubicacion;
